// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Genel ek sorular: Genel Kültür kategorisinde bankada henüz sorulmamış bilgi ve beceriler (bu kategorinin alt alanları: Dünya kültürleri, gelenekler, bayramlar ve yemek kültürü | Türk kültürü, gelenekler, el sanatları, deyim ve atasözlerinin kökenleri | Bilinmesi gereken genel bilgiler: ölçü birimleri, takvim, simgeler, kurumlar | Ünlü yapılar, icatların hikâyesi, ilginç tarih ve dünya bilgileri) (kolay).
const ozCulture5Kolay = <(String, String, List<String>, String)>[
  ('19. yüzyılda İrlanda\'da kiracılara sert davranan bir toprak yöneticisiyle halkın tüm ilişkiyi kesmesi, bugün birçok dilde kullanılan hangi sözcüğün doğmasına yol açmıştır?', 'Boykot', ['Grev', 'Ambargo', 'Sabotaj'], 'Yüzbaşı Charles Boycott\'a karşı 1880\'de uygulanan toplu dışlama, onun soyadını \'boykot\' sözcüğüne dönüştürmüştür.'),
  ('Caz müziğinin simgelerinden olan, metalden yapıldığı hâlde tahta üflemeli sayılan çalgıya adını veren Belçikalı çalgı yapımcısı kimdir?', 'Adolphe Sax', ['Antoine Courtois', 'Theobald Boehm', 'Wilhelm Heckel'], 'Saksofon, 1840\'larda Adolphe Sax tarafından geliştirilmiş ve onun adıyla anılmıştır; ağızlığındaki kamış nedeniyle tahta üflemeliler arasında sınıflandırılır.'),
  ('Rivayete göre oyun masasından kalkmak istemeyen ve etini iki dilim ekmek arasında isteyen bir İngiliz soylusunun unvanı hangi yiyeceğe ad olmuştur?', 'Sandviç', ['Hamburger', 'Tost', 'Kanepe'], 'Anlatıya göre 4. Sandwich Kontu John Montagu, masadan ayrılmadan yiyebilmek için ekmek arasında et istemiş; bu yiyecek onun unvanıyla anılmıştır.'),
  ('Sert iskeletli dev hava gemilerine Türkçede de \'zeplin\' denmesi neyi gösterir?', 'Araçları geliştiren Alman kontunun adının türün adı olmasını', ['Aracın ilk uçtuğu Alman kentinin adını taşımasını', 'Aracı dolduran gazın kimyasal adından türetilmesini', 'Aracın biçimini anlatan Latince bir sözcükten gelmesini'], 'Kont Ferdinand von Zeppelin\'in geliştirdiği sert gövdeli hava gemileri o kadar ünlendi ki onun adı bu araçların genel adına dönüştü.'),
  ('Kot kumaşının İngilizce adı \'denim\', Fransızca \'de Nîmes\' sözünden gelir. Bu ad kumaş hakkında neyi anlatır?', 'Kumaşın Fransa\'daki bir kentle ilişkilendirildiğini', ['Kumaşın ilk kez denizcilerce giyildiğini', 'Kumaşın indigo bitkisinin adını taşıdığını', 'Kumaşın bir terzi ailesinin soyadından geldiğini'], '\'Serge de Nîmes\', güney Fransa\'daki Nîmes kentinin sağlam dokuma kumaşı anlamına gelir; \'denim\' bu sözden kısalmıştır.'),
  ('Desenin parlak ve mat iplik farkıyla kumaşın içine dokunduğu, iki yüzü de kullanılabilen \'damask\' (şam işi) kumaşına adını veren kent hangisidir?', 'Şam', ['Bursa', 'İsfahan', 'Kahire'], 'Damask, Orta Çağ\'da bu kumaşın ünlü üretim ve ticaret merkezi olan Şam\'ın (Damascus) adından gelir.'),
  ('Hindistan ile Pakistan arasındaki dağlık bir bölgenin keçilerinden elde edilen yumuşak yünün Batı dillerinde aynı bölgenin adıyla anılması neyi gösterir?', 'Kaşmir yününün adını bölgeden aldığını', ['Tiftik yününün adını Ankara\'dan aldığını', 'Merinos yününün adını İspanya\'dan aldığını', 'Alpaka yününün adını Peru\'dan aldığını'], 'Kaşmir (cashmere), Kaşmir bölgesinin keçilerinin ince alt tüyünden elde edilen yündür ve adını bu bölgeden alır.'),
  ('Batı geleneğinde evliliğin 25. yılına verilen ad hangisidir?', 'Gümüş yıldönümü', ['Altın yıldönümü', 'Yakut yıldönümü', 'İnci yıldönümü'], 'Geleneksel listede 25. yıl gümüş, 50. yıl altın, 30. yıl inci, 40. yıl yakut ile anılır.'),
  ('Bir çift 1974\'te evlenmiş ve 2024\'te büyük bir kutlama yapmıştır. Geleneksel adlandırmaya göre kutladıkları yıldönümü hangisidir?', 'Altın yıldönümü', ['Gümüş yıldönümü', 'Elmas yıldönümü', 'Yakut yıldönümü'], '2024 − 1974 = 50 yıl eder; evliliğin 50. yılına altın yıldönümü (altın düğün) denir.'),
  ('Geleneksel evlilik yıldönümü listelerinde 60. yıl hangi değerli taşla anılır?', 'Elmas', ['Zümrüt', 'Safir', 'Yakut'], 'Evliliğin 60. yılı elmas yıldönümü olarak bilinir; yakut 40. yılın, safir 45. yılın simgesidir.'),
  ('Dipnotlara gönderme yapmak için kullanılan * işaretinin adı \'asterisk\', Yunancada hangi anlama gelir?', 'Küçük yıldız', ['Küçük çiçek', 'Kesişen çizgi', 'Gizli işaret'], 'Asterisk, Yunanca \'aster\' (yıldız) sözcüğünün küçültme biçiminden gelir ve \'küçük yıldız\' demektir.'),
  ('Bir listede üst satırdaki sözcüğü yeniden yazmamak için kullanılan 〃 işaretine Türkçede ne denir?', 'Denden', ['Kesme', 'Tırnak', 'Düzeltme'], 'Denden işareti, alt alta sıralanan maddelerde bir üst satırdaki sözün aynen tekrarlandığını gösterir.'),
  ('Biyografik kaynaklarda bir kişinin adının yanına konan hançer (†) işareti ne anlama gelir?', 'Kişinin ölmüş olduğu ya da ölüm tarihi', ['Kişinin soylu ve unvanlı bir aileden geldiği', 'Kişinin din adamı olduğu', 'Kişinin bilgisinin doğrulanmadığı'], 'Hançer ya da haç biçimindeki † işareti, soy kütüklerinde ve biyografilerde ölüm tarihini veya kişinin ölmüş olduğunu gösterir.'),
  ('1904 St. Louis Dünya Fuarı\'nda dondurmacının tabağı bitince yandaki tatlıcının ince waffle hamurunu kıvırarak ona kap yaptığı anlatılır. Bu öyküyle yaygınlaşan ürün hangisidir?', 'Dondurma külahı', ['Sandviç dondurma', 'Çubuklu dondurma', 'Dondurmalı kek'], 'Öykünün ayrıntıları tartışılsa da dondurma külahının ABD\'de bu fuarla yaygınlaştığı genel kabul görür.'),
  ('1905\'te 11 yaşındaki Frank Epperson\'un, içinde karıştırma çubuğu bulunan meyveli sodasını soğuk bir gecede dışarıda unutmasının sonucunda ortaya çıkan ürün hangisidir?', 'Çubuklu dondurma', ['Buzlu meyve şurubu', 'Granita', 'Dondurulmuş yoğurt'], 'Sabah donmuş içeceği çubuğundan tutarak yiyen Epperson, yıllar sonra bu buluşu \'Popsicle\' adıyla patentlemiştir.'),
  ('ABD\'de 1886\'da eczacı John Pemberton\'ın ilk olarak bir \'sinir tonik\' şurubu olarak sattığı ve sonradan dünyanın en tanınan gazlı içeceklerinden biri olan ürün hangisidir?', 'Coca-Cola', ['Pepsi-Cola', 'Dr Pepper', 'Sprite'], 'Pemberton, Atlanta\'da eczanelerin gazoz tezgâhlarında satılmak üzere bu şurubu geliştirmiştir; Pepsi ise birkaç yıl sonra başka bir eczacının ürünüdür.'),
  ('Bugünkü satrancın atası kabul edilen ve piyade, süvari, fil ve savaş arabalarını temsil eden taşlarla oynanan oyun hangi bölgede ortaya çıkmıştır?', 'Hindistan', ['Mısır', 'Yunanistan', 'Japonya'], 'Satrancın atası sayılan çaturanga, yaklaşık 6. yüzyılda Hindistan\'da ortaya çıkmış; İran üzerinden İslam dünyasına ve Avrupa\'ya yayılmıştır.'),
  ('Kökeni Çin\'e uzanan, 19×19 çizgili bir tahtada siyah ve beyaz taşlarla alan kapatma esasına dayanan strateji oyunu hangisidir?', 'Go', ['Mahjong', 'Reversi', 'Dama'], 'Go (Çince weiqi) en az 2.500 yıllık bir geçmişe sahiptir; oyuncular taşlarla tahtada daha fazla alanı çevirmeye çalışır.'),
  ('Tavlada her oyuncunun başlangıçta kaç pulu vardır ve tahtada toplam kaç hane bulunur?', '15 pul, 24 hane', ['12 pul, 24 hane', '15 pul, 30 hane', '16 pul, 20 hane'], 'Tavlada her oyuncunun 15 pulu vardır; tahta dört bölümde altışar olmak üzere toplam 24 haneden oluşur.'),
  ('Danimarkalı oyuncak şirketi LEGO\'nun adı Danca hangi sözden türetilmiştir?', '\'İyi oyna\' anlamındaki \'leg godt\'', ['\'Küçük tuğla\' anlamındaki bir sözden', '\'Birleştir\' anlamındaki \'lege sammen\'', 'Kurucusunun doğduğu köyün adından'], 'Şirket kurucusu Ole Kirk Christiansen, Danca \'leg godt\' (iyi oyna) sözünü kısaltarak LEGO adını oluşturmuştur.'),
  ('Spor giyim markası Nike adını hangi kaynaktan alır?', 'Yunan mitolojisindeki zafer tanrıçasından', ['Kurucusunun Japon ortağının soyadından', 'Oregon\'daki bir koşu parkurundan', 'Latincede \'koşmak\' anlamındaki bir fiilden'], 'Nike, Yunan mitolojisinde zaferi kişileştiren kanatlı tanrıçadır; şirket 1971\'de bu adı benimsemiştir.'),
  ('İsveçli otomobil markası Volvo\'nun adı Latincede ne anlama gelir?', 'Yuvarlanırım', ['İlerlerim', 'Güvendeyim', 'Uçarım'], 'Volvo Latince \'volvere\' (yuvarlanmak) fiilinden \'yuvarlanırım\' demektir; ad ilk olarak bir rulman üreticisinin ürününe verilmişti.'),
  ('Adidas markasının adı hangi yolla türetilmiştir?', 'Kurucusunun lakabı ve soyadının birleşmesiyle', ['Yunanca \'koşucu\' anlamına gelen bir sözcükten', 'Almanca \'her gün spor\' sözünün kısaltmasından', 'Kurucunun doğduğu Bavyera köyünün adından'], 'Adolf \'Adi\' Dassler, lakabı \'Adi\' ile soyadının ilk hecesi \'Das\'ı birleştirerek markaya Adidas adını vermiştir.'),
  ('Kahve zinciri Starbucks adını hangi edebî eserden almıştır?', 'Herman Melville\'in \'Moby Dick\' romanındaki bir denizciden', ['Robert Louis Stevenson\'ın \'Define Adası\' romanındaki kaptandan', 'Daniel Defoe\'nun \'Robinson Crusoe\' romanındaki gemiden', 'Jules Verne\'in \'Denizler Altında Yirmi Bin Fersah\'taki denizaltıdan'], 'Starbucks, Moby Dick\'te Kaptan Ahab\'ın birinci yardımcısı olan Starbuck\'ın adından esinlenmiştir.'),
  ('İkinci Dünya Savaşı sırasında Almanya\'da kola şurubu ithal edilemeyince geliştirilen ve adı Almanca \'hayal gücü\' sözcüğünden gelen içecek hangisidir?', 'Fanta', ['Sprite', 'Schweppes', 'Mirinda'], 'Coca-Cola\'nın Alman şubesi, eldeki malzemelerle yeni bir içecek üretmiş; adını \'Fantasie\' sözcüğünden türetmiştir.'),
  ('Topuğun arkasındaki kalın kirişe \'Aşil tendonu\' denmesi hangi söylenceye dayanır?', 'Annesinin onu suya topuğundan tutup batırması', ['Topuğundan yaralanan bir tanrının ölümsüz olması', 'Kahramanın topuğuyla bir canavarı ezmesi', 'Kahramanın en hızlı koşucu olarak ödül alması'], 'Thetis, oğlu Akhilleus\'u Styks Irmağı\'na topuğundan tutarak batırdığı için yalnız topuğu ıslanmamış ve savunmasız kalmıştır.'),
  ('Yunan söylencesinde tanrıların Pandora\'ya verdiği kap açılınca dünyaya kötülükler yayılmış, ama kabın içinde bir şey kalmıştır. Bu kalan şey nedir?', 'Umut', ['Sevgi', 'Bilgelik', 'Ölümsüzlük'], 'Hesiodos\'un anlattığına göre Pandora kabın kapağını kapattığında içinde yalnız umut (elpis) kalmıştır.'),
  ('Ani ve denetimsiz korku anlamındaki \'panik\' sözcüğü, ormanlarda yolcuları ürküttüğüne inanılan hangi mitolojik figürden türemiştir?', 'Keçi ayaklı tanrı Pan', ['Yeraltı tanrısı Hades', 'Savaş tanrısı Ares', 'Gece tanrıçası Nyks'], 'Yunanlılar ıssız yerlerdeki ani korkuyu Pan\'a bağlar, bu korkuya \'panikon\' derlerdi; sözcük buradan dillere geçmiştir.'),
  ('Kendi yansımasına âşık olup göl kıyısından ayrılamayan genç, psikolojide aşırı kendini beğenmeyi anlatan bir kavrama adını vermiştir. Bu kavram hangisidir?', 'Narsisizm', ['Mazoşizm', 'Egoizm', 'Hipokondri'], 'Narkissos söylencesi, aşırı kendine hayranlık anlamındaki narsisizm kavramının kaynağıdır.'),
  ('Ağrı kesici bir ilaç olan morfinin adını aldığı Morpheus, Yunan mitolojisinde neyin tanrısıdır?', 'Düşlerin', ['Ölümün', 'Şarabın', 'Hekimliğin'], 'Morfini 1804\'te ayrıştıran Friedrich Sertürner, maddenin uyku verici etkisi nedeniyle ona düşler tanrısı Morpheus\'un adını vermiştir.'),
  ('\'Müze\' sözcüğünün kökeninde yer alan Musalar (Mousai) mitolojide kimlerdi?', 'Sanatlara esin veren tanrıçalar', ['Tapınakları koruyan savaşçı kadınlar', 'Ölülerin ruhlarını taşıyan kayıkçılar', 'Zeus\'un sarayında hizmet eden devler'], 'Musalar sanatlara ve bilimlere esin veren dokuz tanrıçadır; \'mouseion\' onlara adanmış yer anlamına gelir.'),
  ('Ambulans ve itfaiye araçlarındaki yüksek sesli uyarı düzeneğinin adı, mitolojide şarkılarıyla denizcileri kayalıklara çeken varlıklardan gelir. Bu iki anlam arasındaki ortak nokta hangisidir?', 'İkisi de dikkati güçlü bir sesle kendine çekmek', ['İkisi de yalnızca gece duyulan sesler çıkarmak', 'İkisi de denizcilikte kullanılan bir araç olmak', 'İkisi de tehlikeyi tümüyle ortadan kaldırmak'], 'Sirenler sesleriyle denizcileri büyüler; aynı adı taşıyan uyarı düzeneği de çok güçlü bir sesle herkesin dikkatini çeker.'),
  ('Arjantin\'in adı Latincede hangi madenin adından türemiştir?', 'Gümüş', ['Altın', 'Bakır', 'Kalay'], 'Ad Latince \'argentum\' (gümüş) sözcüğünden gelir; İspanyol kâşifler bölgede gümüş bulunacağına inanmıştı.'),
  ('Avrupalı denizcilerin Maracaibo Gölü kıyısında sular üzerine kazıklarla kurulmuş yerli evleri görünce bölgeye verdikleri ad bugün hangi ülkenin adıdır?', 'Venezuela', ['Kolombiya', 'Guyana', 'Ekvador'], 'Venezuela \'küçük Venedik\' anlamına gelir; kazıklı evler denizcilere suyun üstündeki Venedik\'i hatırlatmıştı.'),
  ('Hollanda\'nın uluslararası resmî adının (Nederland, Netherlands) \'alçak ülkeler\' anlamına gelmesi ülkenin hangi coğrafi özelliğini yansıtır?', 'Topraklarının büyük bölümünün çok alçakta olmasını', ['Dağlarının çok alçak ve yuvarlak olmasını', 'Ülkenin Kuzey Kutbu\'na yakın bulunmasını', 'Nüfusunun büyük bölümünün vadilerde yaşamasını'], 'Hollanda\'nın önemli bir bölümü deniz düzeyinde ya da altındadır ve setlerle korunur; adı bu alçak konumu anlatır.'),
  ('Sanskritçe kökenli \'Singapura\' adı ne anlama gelir?', 'Aslan kenti', ['Kaplan limanı', 'Ejderha adası', 'Fil kapısı'], 'Singapura, Sanskritçe \'simha\' (aslan) ve \'pura\' (kent) sözcüklerinden oluşur; adada aslan yaşamadığı hâlde efsanede bir aslan görüldüğü anlatılır.'),
  ('Güney Amerika\'daki bir ülkenin adının bağımsızlık önderi Simón Bolívar\'dan, bir başka ülkenin adının Kristof Kolomb\'dan geldiği bilinir. Bu ülkeler sırasıyla hangileridir?', 'Bolivya ve Kolombiya', ['Venezuela ve Kolombiya', 'Bolivya ve Ekvador', 'Peru ve Kolombiya'], 'Bolivya adını Simón Bolívar\'dan, Kolombiya ise Kolomb\'un (Columbus) adından almıştır.'),
  ('Çin ve Hindistan\'ın birçok bölgesinde geleneksel cenazelerde yas rengi olarak hangi rengin giyilmesi yaygındır?', 'Beyaz', ['Siyah', 'Kırmızı', 'Sarı'], 'Bu kültürlerde beyaz yasın ve arınmanın rengi sayılır; Batı\'daki siyah yas giysisinin karşılığıdır.'),
  ('ABD\'de ve Avrupa\'nın birçok yerinde kara kedinin önünden geçmesi uğursuz sayılırken Britanya ve Japonya\'da tam tersine uğurlu sayıldığı bilinir. Bu örnek en çok neyi gösterir?', 'Simgelerin anlamının kültüre göre değişebildiğini', ['Batıl inançların bilimsel bulgulara dayandığını', 'Kedilerin bütün dünyada kutsal sayıldığını', 'Uğur inançlarının yalnız Asya\'da yaşadığını'], 'Kara kedi, farklı toplumlarda uğursuzluğun ya da şansın simgesi olabilir; bu, simgelerin anlamının kültüre bağlı olduğunu gösterir.'),
  ('Pek çok Batı ülkesinde dayalı duran bir merdivenin altından geçmenin uğursuz sayılmasının pratik bir açıklaması da yapılır. Bu açıklama hangisidir?', 'Merdivenin ya da üstündeki aletlerin düşebilmesi', ['Merdivenlerin eskiden yalnız kiliselerde bulunması', 'Merdiven altında gölge oluşup yolun görünmemesi', 'Merdivenlerin kötü ruhların yeri sayılması'], 'İnancın dinî yorumları da vardır, ancak sık anılan pratik açıklama merdivenin, üstündeki işçinin ya da alet ve boya kovalarının düşme tehlikesidir.'),
  ('Yeni Zelandalılara uluslararası alanda \'Kiwi\' denmesinin kaynağı nedir?', 'Ülkeye özgü, uçamayan ulusal kuşun adı', ['Ülkede yaygın yetiştirilen meyvenin adı', 'Maori dilinde \'ada halkı\' anlamına gelen sözcük', 'İlk göçmen gemisinin adı'], 'Kivi kuşu Yeni Zelanda\'nın ulusal simgesidir ve halk bu kuşun adıyla anılır; meyveye bu ad sonradan pazarlama amacıyla verilmiştir.'),
  ('Galler bayrağının ortasında hangi figür yer alır?', 'Kırmızı bir ejderha', ['Altın taçlı bir aslan', 'Beyaz bir at', 'Yeşil bir meşe'], 'Galler bayrağında yeşil ve beyaz zemin üzerinde kırmızı ejderha (Y Ddraig Goch) bulunur.'),
  ('İrlanda\'nın resmî devlet simgesi olan ve madeni paralarında da yer alan nesne hangisidir?', 'Arp', ['Kılıç', 'Gemi', 'Taç'], 'İrlanda, bir müzik aletini resmî devlet simgesi olarak kullanan nadir ülkelerdendir; arp pasaportlarda ve madeni paralarda da görülür.'),
  ('Bayrağında Portekizce \'Ordem e Progresso\' yazan ülke hangisidir?', 'Brezilya', ['Portekiz', 'Angola', 'Mozambik'], '\'Düzen ve İlerleme\' anlamındaki bu slogan, pozitivist düşünceden esinlenerek 1889\'da kabul edilen Brezilya bayrağında yer alır.'),
  ('Japonca \'Hinomaru\' olarak anılan Japon bayrağındaki kırmızı daire neyi simgeler?', 'Güneşi', ['Ay\'ı', 'Kan bağını', 'İmparatorluk mührünü'], 'Hinomaru \'güneş dairesi\' anlamına gelir; Japonya\'nın \'Doğan Güneş Ülkesi\' diye anılmasıyla uyumludur.'),
  ('Kesintisiz kullanılan en eski ulusal bayrak olarak kabul edilen ve efsaneye göre 1219\'da bir savaş sırasında gökten düştüğü anlatılan bayrak hangi ülkenindir?', 'Danimarka', ['İsveç', 'Norveç', 'İsviçre'], 'Danimarka bayrağı Dannebrog, kırmızı zemin üzerindeki beyaz haçıyla en eski ulusal bayrak sayılır ve öteki İskandinav bayraklarına örnek olmuştur.'),
  ('Lübnan bayrağının ortasındaki yeşil ağaç, Fenikelilerin gemi yapımında da kullandığı hangi ağaçtır?', 'Sedir', ['Zeytin', 'Hurma', 'Çınar'], 'Lübnan sediri ülkenin simgesidir; eski çağlarda bu ağacın kerestesi gemi ve tapınak yapımında çok değerliydi.'),
  ('Kumaşın boyanmayacak bölümlerinin erimiş mumla kapatılıp sonra boya banyosuna batırılmasıyla desen oluşturulan ve en çok Endonezya\'nın Cava adasıyla özdeşleşen teknik hangisidir?', 'Batik', ['Ikat', 'Kente', 'Shibori'], 'Batikte mum, boyanın kumaşa işlemesini engeller; mum sonradan eritilerek giderilir. Ikatta ise iplikler dokunmadan önce boyanır.'),
  ('Japon kâğıt katlama sanatının adı \'origami\' iki sözcükten oluşur. Bu sözcükler hangi anlamları taşır?', 'Katlamak ve kâğıt', ['Kesmek ve ince kâğıt', 'Kuş ve kanat', 'Sanat ve sabır'], 'Japoncada \'oru\' katlamak, \'kami\' kâğıt demektir; birleşince \'origami\' olur.'),
  ('Türkiye\'de 14 Mart\'ın Tıp Bayramı olarak kutlanması hangi olayın yıldönümüdür?', '1827\'de ilk modern tıp okulu Tıphane-i Âmire\'nin açılması', ['İlk Türk kadın hekimin diploma alması', 'Kızılay\'ın ilk hastanesini açması', 'Türk Tabipleri Birliği\'nin kurulması'], '14 Mart 1827\'de II. Mahmud döneminde Tıphane-i Âmire açılmıştır; bu tarih Tıp Bayramı olarak anılır.'),
  ('Atatürk\'ün 19 Mayıs\'ı Türk gençliğine armağan etmesinin dayandığı olay hangisidir?', '1919\'da Samsun\'a çıkarak Millî Mücadele\'yi başlatması', ['1920\'de Büyük Millet Meclisi\'ni açması', '1923\'te Cumhuriyet\'i ilan etmesi', '1922\'de Büyük Taarruz\'u başlatması'], 'Mustafa Kemal 19 Mayıs 1919\'da Samsun\'a çıkmış, Atatürk 1938\'de bu günü gençliğe armağan etmiştir.'),
  ('Her yıl 26 Eylül\'de kutlanan Dil Bayramı hangi olayın yıldönümüdür?', '1932\'de Birinci Türk Dil Kurultayı\'nın toplanması', ['1928\'de yeni Türk harflerinin kabul edilmesi', '1934\'te Soyadı Kanunu\'nun çıkarılması', '1923\'te ilk Türkçe sözlüğün yayımlanması'], '26 Eylül 1932\'de Dolmabahçe Sarayı\'nda toplanan Birinci Türk Dil Kurultayı\'nın açılış günü Dil Bayramı olarak anılır.'),
  ('Türkiye\'de okka, arşın ve endaze gibi eski ölçüler yerine metre ve kilogram sisteminin kabul edildiği kanun hangisidir?', '1931 tarihli Ölçüler Kanunu', ['1926 tarihli Medeni Kanun', '1928 tarihli Harf Kanunu', '1934 tarihli Soyadı Kanunu'], '1931\'de kabul edilen Ölçüler Kanunu ile metrik sisteme geçilmiş, uygulama 1933\'te zorunlu hâle gelmiştir.'),
  ('Her yıl 22 Nisan\'da kutlanan Dünya Günü (Earth Day) ilk kez 1970\'te ABD\'de hangi amaçla düzenlenmiştir?', 'Çevre kirliliğine dikkat çekmek', ['Ay\'a inişi kutlamak', 'Nükleer silahların yasaklanmasını istemek', 'Gezegenlerin keşfini anmak'], '1970\'te milyonlarca Amerikalının katıldığı gösterilerle başlayan Dünya Günü, çevre sorunlarına dikkat çekmeyi amaçlar.'),
  ('Her yıl 22 Mart\'ta kutlanan ve BM\'nin 1993\'ten beri tanıdığı uluslararası gün hangisidir?', 'Dünya Su Günü', ['Dünya Ormancılık Günü', 'Dünya Meteoroloji Günü', 'Dünya Kitap Günü'], 'BM Genel Kurulu 1992\'de 22 Mart\'ı Dünya Su Günü ilan etmiş, ilk kutlama 1993\'te yapılmıştır.'),
  ('Latin Amerika ülkelerinin çoğunda kullanılan \'peso\' adının İspanyolcadaki anlamı nedir?', 'Ağırlık', ['Gümüş', 'Kral', 'Yuvarlak'], 'Peso \'ağırlık\' demektir; para birimi, belli ağırlıktaki gümüş sikkelerden adını almıştır. Sterlin (pound) da benzer biçimde bir ağırlık ölçüsünden gelir.'),
  ('Antik Roma\'nın gümüş sikkesi \'denarius\'un adı bugün hangi para biriminin adında yaşamaktadır?', 'Dinar', ['Dirhem', 'Drahmi', 'Duka'], 'Denarius, Arapça \'dinar\' adının kaynağıdır; dinar bugün Kuveyt, Ürdün, Sırbistan gibi ülkelerde kullanılır.'),
  ('Çek korunası ile İsveç ve Danimarka kronunun adları aynı anlamı taşır. Bu anlam nedir?', 'Taç', ['Gümüş', 'Halk', 'Kartal'], 'Koruna, krona ve krone adları Latince \'corona\' (taç) sözcüğünden gelir; bu sikkelerin üzerinde çoğu zaman kraliyet tacı bulunurdu.'),
  ('19. yüzyılda Britanya\'da kentlerin her birinin kendi yerel güneş saatini kullanmaktan vazgeçip ortak bir saati benimsemesini en çok hangi gelişme zorunlu kılmıştır?', 'Demiryolu tarifeleri', ['Telefonun icadı', 'Fabrika vardiyalarının uzaması', 'Yaz saati uygulaması'], 'Tren tarifeleri her istasyonda farklı yerel saat olunca karmaşıklaştığından demiryolu şirketleri Greenwich saatini ortak \'demiryolu saati\' olarak benimsemiştir.'),
  ('Pul koleksiyonculuğuna verilen ad hangisidir?', 'Filateli', ['Nümismatik', 'Kartografi', 'Bibliyografi'], 'Pul toplama ve inceleme uğraşına filateli, madeni para ve madalya koleksiyonculuğuna ise nümismatik denir.'),
  ('İspanya\'da geleneksel olarak bir kişinin iki soyadı taşıması nasıl açıklanır?', 'Biri babanın, biri annenin ilk soyadıdır.', ['Birincisi doğduğu kentin, ikincisi ailenin adıdır.', 'İkisi de babanın ailesinden gelir.', 'Biri evlenince eşten alınır, diğeri doğuştandır.'], 'İspanyol adlandırma geleneğinde kişi babasının ve annesinin ilk soyadlarını birlikte taşır; kadınlar evlenince soyadlarını değiştirmez.'),
  ('Rusçada \'Anton Pavloviç Çehov\' adındaki \'Pavloviç\' bölümü neyi gösterir?', 'Babasının adının Pavel olduğunu', ['Doğduğu kentin Pavlovsk olduğunu', 'Dedesinin mesleğini', 'Vaftiz babasının soyadını'], 'Rus adlarında ortadaki bölüm baba adıdır (patronim); erkeklerde \'-oviç/-eviç\', kadınlarda \'-ovna/-evna\' eki alır.'),
  ('Macaristan\'da ünlü besteci Ferenc Liszt\'in adı Macarca yazıldığında \'Liszt Ferenc\' biçimini alır. Bu durum Macarca adlandırma hakkında neyi gösterir?', 'Soyadının ada göre önce yazıldığını', ['Macarlarda soyadı bulunmadığını', 'Adların her zaman Latince yazıldığını', 'Babanın adının sona eklendiğini'], 'Macarlar, Çinliler, Japonlar ve Koreliler gibi soyadını adın önünde kullanır; Batı dillerinde ise bu ad sıklıkla yer değiştirerek yazılır.'),
  ('İngilizcedeki Smith, Taylor ve Baker soyadlarının ortak kökeni nedir?', 'Atalarının yaptığı meslekler', ['Yaşadıkları yerlerin adları', 'Babalarının adları', 'Fiziksel özellikleri'], 'Smith demirci, Taylor terzi, Baker fırıncı demektir; Türkçedeki Demirci, Terzi gibi soyadlarına benzer biçimde meslekten türemiştir.'),
  ('Gece giyilen pijamanın adı Farsçadan gelir. Bu sözcüğün özgün anlamı nedir?', 'Bacak giysisi', ['Uyku elbisesi', 'Gece örtüsü', 'İpek kumaş'], 'Farsça \'pay\' (bacak) ve \'came\' (giysi) sözcüklerinden oluşur; İngilizler sözcüğü Hindistan\'da tanımıştır.'),
  ('Salgın dönemlerinde uygulanan \'karantina\' sözcüğü Venedik lehçesinde hangi sayıyla ilişkilidir?', 'Kırk', ['Yedi', 'On dört', 'Otuz'], 'Venedik\'te veba döneminde gemiler limana girmeden önce kırk gün (quaranta giorni) bekletilirdi; \'karantina\' buradan gelir.'),
  ('Kaptan Cook\'un 18. yüzyılda Tonga\'da öğrendiği ve \'yasak, dokunulmaz\' anlamına gelen sözcük bugün dünya dillerine hangi biçimde yerleşmiştir?', 'Tabu', ['Totem', 'Mana', 'Fetiş'], 'Tonga dilindeki \'tapu\' kutsal ya da yasak olan şeyleri anlatır; Cook\'un yazılarıyla \'taboo/tabu\' olarak Avrupa dillerine geçmiştir.'),
  ('Tehlike anında çalan \'alarm\' sözcüğü İtalyanca hangi sesleniş biçiminden gelir?', '\'All\'arme!\' yani \'Silah başına!\'', ['\'Allarga!\' yani \'Açıl!\'', '\'Alla mano!\' yani \'Ele!\'', '\'Al mare!\' yani \'Denize!\''], 'İtalyanca \'all\'arme\' (\'silahlara!\') çağrısı, askerleri savunmaya çağıran bir haykırıştı; zamanla genel uyarı anlamı kazanmıştır.'),
];
